public InputStream getInputStream(ZipArchiveEntry ze) throws IOException, ZipException {
    OffsetEntry offsetEntry = entries.get(ze);
    if (offsetEntry == null) {
        return null;
    }
    ZipUtil.checkRequestedFeatures(ze);
    long start = offsetEntry.dataOffset;
    BoundedInputStream bis = new BoundedInputStream(start, ze.getCompressedSize());
    switch (ze.getMethod()) {
        case ZipArchiveEntry.STORED:
            return bis;
        case ZipArchiveEntry.DEFLATED:
            bis.addDummy();
            final Inflater inflater = new Inflater(true);
            return new InflaterInputStream(bis, inflater) {
                @Override
                public void close() throws IOException {
                    super.close();
                    inflater.end();
                }
            };
        default:
            throw new ZipException("Found unsupported compression method " + ze.getMethod());
    }
}
```

